function normRoutine(raw) {
  const p = raw?.program ?? null;
  const weeks = Array.isArray(p?.weeks) ? p.weeks : [];
  const idx = Number.isFinite(p?.current_week) ? Math.min(Math.max(p.current_week, 0), Math.max(weeks.length - 1, 0)) : 0;
  return {
    program: p && { ...p, weeks, current_week: idx },
    week: weeks[idx] ?? null,
    items: Array.isArray(weeks[idx]?.items) ? weeks[idx].items : [],
    stats: { done: raw?.stats?.done ?? 0, streak: raw?.stats?.streak ?? 0 },
  };
}
